public static function hasInternet():Bool
	{
		try {
			var r = requestText("https://www.google.com/");
			return true;
		} catch (e:HttpError) {
			Logs.trace('[HttpUtil.hasInternet] Failed: ${e.toString()}', WARNING);
			return false;
		}
	}
